insert into constraint_types(code,name,sort_order) values
('SAFETY','Safety',10),('SELECTIVITY','Selectivity',20),('PK','Pharmacokinetics',30),('DISTRIBUTION','Distribution',40),('ADMINISTRATION','Administration',50),('EFFICACY_CEILING','Efficacy ceiling',60),('RESISTANCE','Resistance',70),('STABILITY','Stability',80),('DELIVERY','Delivery',90);
insert into constraint_types(parent_id,code,name,sort_order) select id,'SAFETY_ON_TARGET_OFF_TISSUE','On-target, off-tissue safety',11 from constraint_types where code='SAFETY';
insert into constraint_types(parent_id,code,name,sort_order) select id,'SAFETY_OFF_TARGET','Off-target safety',12 from constraint_types where code='SAFETY';
insert into constraint_types(parent_id,code,name,sort_order) select id,'SAFETY_ORGAN_TOXICITY','Organ toxicity',13 from constraint_types where code='SAFETY';
insert into constraint_types(parent_id,code,name,sort_order) select id,'SAFETY_IMMUNE_TOXICITY','Immune toxicity',14 from constraint_types where code='SAFETY';
insert into constraint_types(parent_id,code,name,sort_order) select p.id,v.code,v.name,v.ord from constraint_types p cross join (values ('SELECTIVITY_CELL','Cell selectivity',21),('SELECTIVITY_TISSUE','Tissue selectivity',22),('SELECTIVITY_ISOFORM','Isoform selectivity',23)) v(code,name,ord) where p.code='SELECTIVITY';
insert into constraint_types(parent_id,code,name,sort_order) select p.id,v.code,v.name,v.ord from constraint_types p cross join (values ('PK_SHORT_HALF_LIFE','Short half-life',31),('PK_RAPID_CLEARANCE','Rapid clearance',32),('PK_CMAX_TOXICITY','Cmax toxicity',33),('PK_INADEQUATE_TROUGH','Inadequate trough',34)) v(code,name,ord) where p.code='PK';
insert into constraint_types(parent_id,code,name,sort_order) select p.id,v.code,v.name,v.ord from constraint_types p cross join (values ('DISTRIBUTION_CNS','CNS access',41),('DISTRIBUTION_TUMOR','Tumor access',42),('DISTRIBUTION_INTRACELLULAR','Intracellular distribution',43),('DISTRIBUTION_WRONG_CELL','Wrong-cell distribution',44)) v(code,name,ord) where p.code='DISTRIBUTION';
